      };

      const theme = ThemeConverter.convertToTheme(themeConfig);

      expect(theme.palette.mode).toBe('dark');
    });

    it('should convert legacy format theme', () => {
      const legacyTheme = {
        palette: {
          mode: 'dark' as const,
